/**
 * A mode message: a user prompt generated by an agent mode (e.g. review).
 * The UI renders it with a short text + mode badge instead of the full
 * prompt text. The full prompt — and any images attached to it — is sent
 * to the LLM via toLlmMessages.
 *
 * The message shape itself lives in ai/types.ts (with every other message
 * shape); this module builds and reads it.
 */
import type { ImageContent, ModeMessage } from "../ai/types.ts";

/** Input data the client sends when a mode prompt is submitted. */
export interface ModePrompt {
  modeId: string;
  optionId: string;
  modeLabel: string;
  shortText: string;
}

/** Build a ModeMessage from a ModePrompt + full prompt text. `images` are
 * the composer attachments (`[]` when the user attached none). `steered`
 * marks a prompt delivered into the run that was already active; only the
 * delivery site (the session agent) knows that fact, so callers that
 * merely render or replay a mode prompt never set it. */
export function buildModeMessage(
  prompt: ModePrompt,
  fullPrompt: string,
  images: ImageContent[],
  timestamp: number,
  steered?: boolean,
): ModeMessage {
  return {
    role: "mode",
    modeId: prompt.modeId,
    optionId: prompt.optionId,
    modeLabel: prompt.modeLabel,
    shortText: prompt.shortText,
    fullPrompt,
    images,
    ...(steered === true ? { steered } : {}),
    timestamp,
  };
}

/** The agent-visible text of a mode message: the full prompt. Images
 * attached to the prompt are sent alongside it as content blocks of their
 * own (see toLlmMessages). */
export function modeFullPromptText(message: ModeMessage): string {
  return message.fullPrompt;
}
